  padding: 5rem 1.5rem;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.feature-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  padding: 2rem;
  box-shadow: var(--shadow-card);
  border: 1px solid rgba(168, 212, 245, 0.2);
  transition: transform 250ms ease, box-shadow 250ms ease;
}

.feature-card:hover { transform: translateY(-4px); box-shadow: 0 8px 32px rgba(13, 31, 60, 0.12); }

.feature-icon { font-size: 2rem; color: var(--color-accent); margin-bottom: 1rem; }

.feature-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-deep);
  margin-bottom: 0.5rem;
}

.feature-card p { color: var(--color-muted); line-height: 1.65; }

