:root {
  --color-bg: #f5f7fa;
  --color-surface: #ffffff;
  --color-deep: #0d1f3c;
  --color-mid: #1a3a5c;
  --color-ice: #a8d4f5;
  --color-water: #2a6496;
  --color-text: #1a1a2e;
  --color-muted: #5a6a7e;
  --color-accent: #1e6fa8;
  --color-accent-dark: #155a8a;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --radius-sm: 6px;
  --radius-md: 12px;
  --shadow-card: 0 4px 24px rgba(13, 31, 60, 0.08);
  --shadow-btn: 0 2px 8px rgba(30, 111, 168, 0.3);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
}

/* ── Nav ───────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(245, 247, 250, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(168, 212, 245, 0.3);
}

.top-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1100px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
}

.nav-logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-deep);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  color: var(--color-muted);
  text-decoration: none;
  font-size: 0.9rem;
  transition: color 150ms ease;
}

.nav-links a:hover { color: var(--color-accent); }

/* ── Hero ──────────────────────────────────────────── */
.hero-section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 3rem;
  max-width: 1100px;
  margin: 0 auto;
  padding: 6rem 1.5rem;
  min-height: 80vh;
}

.hero-content { flex: 1; max-width: 540px; }

.hero-heading {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--color-deep);
  margin-bottom: 1.25rem;
}

.hero-subtext {
  font-size: 1.15rem;
  color: var(--color-muted);
  margin-bottom: 2rem;
  max-width: 42ch;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

/* ── Iceberg visual ────────────────────────────────── */
.hero-visual {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: center;
}

.iceberg-wrap { display: flex; flex-direction: column; align-items: center; }

.iceberg-tip {
  width: 0;
  height: 0;
  border-left: 56px solid transparent;
  border-right: 56px solid transparent;
  border-bottom: 84px solid var(--color-ice);
  filter: drop-shadow(0 -4px 14px rgba(168, 212, 245, 0.55));
}

.waterline {
  width: 160px;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--color-water), transparent);
}

.iceberg-body {
  width: 0;
  height: 0;
  border-left: 96px solid transparent;
  border-right: 96px solid transparent;
  border-top: 152px solid rgba(30, 111, 168, 0.22);
  filter: blur(1px);
}

/* ── Buttons ───────────────────────────────────────── */
.btn-primary {
  display: inline-block;
  padding: 0.75rem 1.75rem;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-family: var(--font-sans);
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  transition: background-color 150ms ease, transform 150ms ease;
}

.btn-primary:hover { background: var(--color-accent-dark); transform: translateY(-1px); }
.btn-primary:active { transform: translateY(0); }
.btn-primary:disabled { opacity: 0.65; cursor: default; transform: none; }

.btn-secondary {
  display: inline-block;
  padding: 0.75rem 1.75rem;
  background: transparent;
  color: var(--color-accent);
  border: 2px solid var(--color-accent);
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-family: var(--font-sans);
  font-weight: 600;
  text-decoration: none;
  transition: background 150ms ease, color 150ms ease;
}

.btn-secondary:hover { background: var(--color-accent); color: #fff; }

/* ── Sections ──────────────────────────────────────── */
.section-heading {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  color: var(--color-deep);
  text-align: center;
  letter-spacing: -0.02em;
  margin-bottom: 3.5rem;
}

/* ── Features ──────────────────────────────────────── */
.features-section {
  max-width: 1100px;
  margin: 0 auto;
  padding: 5rem 1.5rem;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.feature-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  padding: 2rem;
  box-shadow: var(--shadow-card);
  border: 1px solid rgba(168, 212, 245, 0.2);
  transition: transform 250ms ease, box-shadow 250ms ease;
}

.feature-card:hover { transform: translateY(-4px); box-shadow: 0 8px 32px rgba(13, 31, 60, 0.12); }

.feature-icon { font-size: 2rem; color: var(--color-accent); margin-bottom: 1rem; }

.feature-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-deep);
  margin-bottom: 0.5rem;
}

.feature-card p { color: var(--color-muted); line-height: 1.65; }

/* ── About ─────────────────────────────────────────── */
.about-section {
  background: linear-gradient(135deg, var(--color-deep) 0%, var(--color-mid) 100%);
  padding: 6rem 1.5rem;
}

.about-content { max-width: 680px; margin: 0 auto; text-align: center; }

.about-content h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
}

.about-content p {
  font-size: 1.1rem;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.75;
  margin-bottom: 1rem;
}

.about-content .tagline {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-ice);
  margin-bottom: 0;
}

/* ── Contact ───────────────────────────────────────── */
.contact-section { max-width: 540px; margin: 0 auto; padding: 5rem 1.5rem; }

.contact-form { display: flex; flex-direction: column; gap: 1.25rem; }

.form-field { display: flex; flex-direction: column; gap: 0.35rem; }

.form-field label { font-size: 0.875rem; font-weight: 600; color: var(--color-text); }

.form-field input,
.form-field textarea {
  padding: 0.75rem 1rem;
  border: 1.5px solid rgba(168, 212, 245, 0.5);
  border-radius: var(--radius-sm);
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background: var(--color-surface);
  transition: border-color 150ms ease, box-shadow 150ms ease;
  resize: vertical;
}

.form-field input:focus,
.form-field textarea:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(30, 111, 168, 0.15);
}

/* ── Footer ────────────────────────────────────────── */
.site-footer {
  text-align: center;
  padding: 1.5rem;
  color: var(--color-muted);
  font-size: 0.875rem;
  border-top: 1px solid rgba(168, 212, 245, 0.3);
}

/* ── Responsive ────────────────────────────────────── */
@media (max-width: 768px) {
  .hero-section {
    flex-direction: column-reverse;
    padding: 3rem 1.5rem;
    min-height: auto;
    text-align: center;
  }

  .hero-subtext { margin-inline: auto; }
  .hero-actions { justify-content: center; }
}

@media (max-width: 480px) {
  .nav-links { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .feature-card, .btn-primary, .btn-secondary, .nav-links a { transition: none; }
}

