.presence-both .cn-presence-tag { color: var(--text-muted); }

.cn-card-name {
  font-family: var(--font-display);
  font-size: 1.05rem;
  color: var(--amber-deep);
  font-weight: 400;
}

.cn-card-title {
  font-size: 0.72rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

.cn-card-bond {
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: 0.2rem;
}

/* ── Detail panel ───────────────────────────────────── */
.cn-detail {
  border-left: 1px solid var(--border);
  overflow-y: auto;
  position: sticky;
  top: 0;
  max-height: calc(100vh - 120px);
  background: rgba(255, 251, 240, 0.97);
}

.cn-detail-inner {
  padding: 2rem 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.cn-detail-close {
  align-self: flex-end;
  background: transparent;
  border: none;
  font-size: 0.9rem;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  transition: color var(--transition);
}

.cn-detail-close:hover { color: var(--gold-600); }

.cn-detail-eyebrow {
  font-size: 0.65rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.cn-detail-name {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 400;
  color: var(--amber-deep);
  line-height: 1;
}

.cn-detail-title {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-top: -0.5rem;
}

.cn-detail-entries {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 0.25rem;
}

.cn-detail-entry {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.cn-entry-label {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.15rem 0.5rem;
  border-radius: 3px;
  align-self: flex-start;
}

.cn-label-a {
  background: rgba(96, 165, 250, 0.15);
  color: #1d4ed8;
}

.cn-label-b {
  background: rgba(52, 211, 153, 0.15);
  color: #065f46;
}

.cn-entry-text {
  font-size: 0.85rem;
  line-height: 1.7;
  color: var(--text-primary);
}

.cn-detail-quote {
  margin-top: 0.5rem;
  padding: 0.75rem 1rem;
  border-left: 2px solid var(--gold-300);
  background: rgba(252, 211, 77, 0.08);
  border-radius: 0 4px 4px 0;
}

.cn-detail-quote p {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.875rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

.cn-detail-quote cite {
  display: block;
  margin-top: 0.5rem;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  font-style: normal;
}

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 900px) {
  .cn-body {
    grid-template-columns: 1fr;
  }

  .cn-detail {
    position: static;
    max-height: none;
    border-left: none;
    border-top: 1px solid var(--border);
  }

  .cn-grid {
    padding: 1.5rem;
  }

  .cn-filters {
    padding: 1rem 1.5rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cn-card, .cn-filter-btn { transition: none; }
}

