589	/* ── Responsive ─────────────────────────────────────── */
590	@media (max-width: 768px) {
591	  .tl-header {
592	    grid-template-columns: 1fr;
593	    grid-template-rows: auto auto auto;
594	    text-align: center;
595	    padding: 1.5rem;
596	    gap: 0.75rem;
597	  }
598	
599	  .tl-back, .tl-compare-toggle { justify-self: center; }
600	
601	  .tl-grid {
602	    grid-template-columns: 1fr;
603	    padding: 1.5rem;
604	  }
605	
606	  .tl-column + .tl-column {
607	    border-left: none;
608	    border-top: 1px solid var(--border);
609	    margin-top: 2rem;
610	    padding-top: 2rem;
611	  }
612	
613	  .tl-comparison { padding: 1rem 1.5rem; }
614	}
615	
616	@media (prefers-reduced-motion: reduce) {
617	  .beat-card { transition: none; }
618	}
619	
620	/* ════════════════════════════════════════════════════════
621	   CONNECTIONS PAGE
622	   ════════════════════════════════════════════════════════ */
623	
624	.cn-page {
625	  min-height: 100vh;
626	  background: var(--gold-100);
627	  background-image:
628	    radial-gradient(ellipse 80% 50% at 50% 0%, rgba(251, 191, 36, 0.14) 0%, transparent 60%);
629	  font-family: var(--font-body);
630	  color: var(--text-primary);
631	  display: flex;
632	  flex-direction: column;
633	}
634	
635	.cn-header-right { justify-self: end; }
636	
637	/* ── Filters ────────────────────────────────────────── */
638	.cn-filters {
639	  display: flex;
640	  flex-wrap: wrap;
641	  gap: 0.5rem;
642	  padding: 1.25rem 3rem;
643	  border-bottom: 1px solid var(--border);
644	}
645	
646	.cn-filter-btn {
647	  padding: 0.3rem 0.9rem;
648	  background: transparent;
649	  border: 1px solid var(--border);
650	  border-radius: 100px;
651	  font-size: 0.72rem;
652	  font-family: var(--font-body);
653	  font-weight: 600;
654	  letter-spacing: 0.05em;
655	  color: var(--text-muted);
656	  cursor: pointer;
657	  transition: all var(--transition);
658	}
659	
660	.cn-filter-btn:hover {
661	  border-color: var(--gold-400);
662	  color: var(--gold-600);
663	}
664	
665	.cn-filter-btn.is-active {
666	  background: var(--gold-500);
667	  border-color: var(--gold-500);
668	  color: #fff;
669	}
670	
671	/* ── Body layout ────────────────────────────────────── */
672	.cn-body {
673	  display: grid;
674	  grid-template-columns: 1fr 340px;
675	  flex: 1;
676	  min-height: 0;
677	}
678	
679	/* ── Card grid ──────────────────────────────────────── */
680	.cn-grid {
681	  display: grid;
682	  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
683	  gap: 0.75rem;
684	  padding: 2rem 3rem;
685	  align-content: start;
686	  overflow-y: auto;
687	}
688	
689	/* Bond color coding via dot */
690	.cn-bond-dot {
691	  display: inline-block;
692	  width: 8px;
693	  height: 8px;
694	  border-radius: 50%;
695	  flex-shrink: 0;
696	}
697	
698	.bond-divine   .cn-bond-dot { background: #a78bfa; }
699	.bond-family   .cn-bond-dot { background: #f97316; }
700	.bond-ally     .cn-bond-dot { background: var(--gold-400); }
701	.bond-ward     .cn-bond-dot { background: #34d399; }
702	.bond-child    .cn-bond-dot { background: #fb923c; }
703	.bond-adversary .cn-bond-dot { background: #f87171; }
704	
705	.cn-card {
706	  background: rgba(255, 251, 240, 0.6);
707	  border: 1px solid var(--border);
708	  border-radius: 8px;
709	  padding: 1rem;
710	  text-align: left;
711	  cursor: pointer;
712	  font-family: var(--font-body);
713	  transition: border-color var(--transition), background var(--transition), transform var(--transition);
714	  display: flex;
715	  flex-direction: column;
716	  gap: 0.3rem;
717	}
718	
719	.cn-card:hover {
720	  border-color: rgba(245, 158, 11, 0.4);
721	  background: rgba(255, 251, 240, 0.9);
722	  transform: translateY(-2px);
723	}
724	
725	.cn-card.is-selected {
726	  border-color: var(--gold-500);
727	  background: rgba(255, 251, 240, 0.95);
728	  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
729	}
730	
731	.cn-card-top {
732	  display: flex;
733	  align-items: center;
734	  justify-content: space-between;
735	  margin-bottom: 0.2rem;
736	}
737	
738	.cn-presence-tag {
739	  font-size: 0.6rem;
740	  letter-spacing: 0.08em;
741	  text-transform: uppercase;
742	  color: var(--text-muted);
743	  opacity: 0.7;
744	}
745	
746	.presence-a  .cn-presence-tag { color: #60a5fa; opacity: 1; }
747	.presence-b  .cn-presence-tag { color: #34d399; opacity: 1; }
748	.presence-both .cn-presence-tag { color: var(--text-muted); }
749	
750	.cn-card-name {
751	  font-family: var(--font-display);
752	  font-size: 1.05rem;
753	  color: var(--amber-deep);
754	  font-weight: 400;
755	}
756	
757	.cn-card-title {
758	  font-size: 0.72rem;
759	  color: var(--text-secondary);
760	  line-height: 1.4;
761	}
762	
763	.cn-card-bond {
764	  font-size: 0.65rem;
765	  letter-spacing: 0.08em;
766	  text-transform: uppercase;
767	  color: var(--text-muted);
768	  margin-top: 0.2rem;
769	}
770	
771	/* ── Detail panel ───────────────────────────────────── */
772	.cn-detail {
773	  border-left: 1px solid var(--border);
774	  overflow-y: auto;
775	  position: sticky;
776	  top: 0;
777	  max-height: calc(100vh - 120px);
778	  background: rgba(255, 251, 240, 0.97);
779	}
780	
781	.cn-detail-inner {
782	  padding: 2rem 1.75rem;
783	  display: flex;
784	  flex-direction: column;
785	  gap: 1rem;
786	}
787	
788	.cn-detail-close {
789	  align-self: flex-end;
790	  background: transparent;
791	  border: none;
792	  font-size: 0.9rem;
793	  color: var(--text-muted);
794	  cursor: pointer;
795	  padding: 0.25rem 0.5rem;
796	  transition: color var(--transition);
797	}
798	
799	.cn-detail-close:hover { color: var(--gold-600); }
800	
801	.cn-detail-eyebrow {
802	  font-size: 0.65rem;
803	  letter-spacing: 0.14em;
804	  text-transform: uppercase;
805	  color: var(--text-muted);
806	}
807	
808	.cn-detail-name {
809	  font-family: var(--font-display);
810	  font-size: 2rem;
811	  font-weight: 400;
812	  color: var(--amber-deep);
813	  line-height: 1;
814	}
815	
816	.cn-detail-title {
817	  font-family: var(--font-display);
818	  font-style: italic;
819	  font-size: 0.875rem;
820	  color: var(--text-secondary);
821	  margin-top: -0.5rem;
822	}
823	
824	.cn-detail-entries {
825	  display: flex;
826	  flex-direction: column;
827	  gap: 1rem;
828	  margin-top: 0.25rem;
829	}
830	
831	.cn-detail-entry {
832	  display: flex;
833	  flex-direction: column;
834	  gap: 0.4rem;
835	}
836	
837	.cn-entry-label {
838	  font-size: 0.62rem;
839	  font-weight: 700;
840	  letter-spacing: 0.12em;
841	  text-transform: uppercase;
842	  padding: 0.15rem 0.5rem;
843	  border-radius: 3px;
844	  align-self: flex-start;
845	}
846	
847	.cn-label-a {
848	  background: rgba(96, 165, 250, 0.15);
849	  color: #1d4ed8;
850	}
851	
852	.cn-label-b {
853	  background: rgba(52, 211, 153, 0.15);
854	  color: #065f46;
855	}
856	
857	.cn-entry-text {
858	  font-size: 0.85rem;
859	  line-height: 1.7;
860	  color: var(--text-primary);
861	}
862	
863	.cn-detail-quote {
864	  margin-top: 0.5rem;
865	  padding: 0.75rem 1rem;
866	  border-left: 2px solid var(--gold-300);
867	  background: rgba(252, 211, 77, 0.08);
868	  border-radius: 0 4px 4px 0;
869	}
870	
871	.cn-detail-quote p {
872	  font-family: var(--font-display);
873	  font-style: italic;
874	  font-size: 0.875rem;
875	  line-height: 1.65;
876	  color: var(--text-secondary);
877	}
878	
879	.cn-detail-quote cite {
880	  display: block;
881	  margin-top: 0.5rem;
882	  font-size: 0.68rem;
883	  letter-spacing: 0.08em;
884	  text-transform: uppercase;
885	  color: var(--text-muted);
886	  font-style: normal;
887	}
888	
889	/* ── Responsive ─────────────────────────────────────── */
890	@media (max-width: 900px) {
891	  .cn-body {
892	    grid-template-columns: 1fr;
893	  }
894	
895	  .cn-detail {
896	    position: static;
897	    max-height: none;
898	    border-left: none;
899	    border-top: 1px solid var(--border);
900	  }
901	
902	  .cn-grid {
903	    padding: 1.5rem;
904	  }
905	
906	  .cn-filters {
907	    padding: 1rem 1.5rem;
908	  }
909	}
910	
911	@media (prefers-reduced-motion: reduce) {
912	  .cn-card, .cn-filter-btn { transition: none; }
913	}
