file.content:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  /* Warm amber-gold palette */
  --gold-100: #fffbf0;
  --gold-200: #fef3c7;
  --gold-300: #fcd34d;
  --gold-400: #f59e0b;
  --gold-500: #d97706;
  --gold-600: #b45309;
  --amber-deep: #78350f;
  --ember:      #92400e;

  --text-primary:   #1c0a00;
  --text-secondary: #6b3a12;
  --text-muted:     #a16207;

  --surface:        rgba(255, 251, 240, 0.6);
  --surface-solid:  #fffbf0;

  --border: rgba(245, 158, 11, 0.25);

  --font-display: Georgia, "Times New Roman", serif;
  --font-body:    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --transition: 200ms ease;
}

html, body, #root {
  height: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--text-primary);
  background: var(--gold-100);
  /* Radial warm glow behind center */
  background-image:
    radial-gradient(ellipse 60% 70% at 50% 50%, rgba(251, 191, 36, 0.18) 0%, transparent 70%),
    radial-gradient(ellipse 100% 100% at 50% -10%, rgba(245, 158, 11, 0.12) 0%, transparent 60%);
}

/* ── Layout grid ────────────────────────────────────── */
.viewport {
  display: grid;
  grid-template-columns: 200px 1fr 200px;
  height: 100vh;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 2rem;
  overflow: hidden;
}

/* ── Left column ────────────────────────────────────── */
.left-col {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-start;
  padding: 3rem 1.5rem 3rem 0;
  border-right: 1px solid var(--border);
}

.sigil {
  width: 88px;
  height: 88px;
  color: var(--gold-500);
  opacity: 0.85;
  filter: drop-shadow(0 0 12px rgba(245, 158, 11, 0.4));
}

.side-nav {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.nav-item {
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-decoration: none;
  padding: 0.3rem 0;
  border-left: 2px solid transparent;
  padding-left: 0.75rem;
  transition: color var(--transition), border-color var(--transition);
}

.nav-item:hover,
.nav-item.is-active {
  color: var(--gold-500);
  border-left-color: var(--gold-500);
}

.side-label {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  opacity: 0.6;
}

/* ── Center column ──────────────────────────────────── */
.center-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 3rem 3rem;
  gap: 2.5rem;
}

.hero-header { display: flex; flex-direction: column; align-items: center; gap: 0.6rem; }

.eyebrow {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold-500);
}

.hero-name {
  font-family: var(--font-display);
  font-size: clamp(4.5rem, 9vw, 8rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--amber-deep);
  text-shadow:
    0 0 60px rgba(245, 158, 11, 0.35),
    0 2px 4px rgba(0, 0, 0, 0.08);
}

.hero-epithet {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--text-secondary);
  letter-spacing: 0.02em;
}

.hero-quote {
  border-left: none;
  max-width: 38ch;
}

.hero-quote p {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 1.05rem;
  line-height: 1.75;
  color: var(--text-secondary);
  position: relative;
}

.hero-quote p::before {
  content: '\201C';
  position: absolute;
  left: -1.2rem;
  top: -0.25rem;
  font-size: 2.5rem;
  color: var(--gold-300);
  line-height: 1;
  font-family: var(--font-display);
}

.hero-quote p::after {
  content: '\201D';
  font-size: 2.5rem;
  color: var(--gold-300);
  line-height: 0;
  vertical-align: -0.6rem;
  font-family: var(--font-display);
  margin-left: 0.15rem;
}

.hero-cta-row {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* ── Buttons ────────────────────────────────────────── */
.btn-primary {
  display: inline-block;
  padding: 0.65rem 1.75rem;
  background: var(--gold-500);
  color: #fff;
  border: none;
  border-radius: 4px;
  font-size: 0.85rem;
  font-family: var(--font-body);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-decoration: none;
  cursor: pointer;
  box-shadow: 0 2px 12px rgba(217, 119, 6, 0.4);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.btn-primary:hover {
  background: var(--gold-600);
  transform: translateY(-1px);
  box-shadow: 0 4px 18px rgba(217, 119, 6, 0.5);
}

.btn-ghost {
  display: inline-block;
  padding: 0.65rem 1.5rem;
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 0.85rem;
  font-family: var(--font-body);
  font-weight: 500;
  text-decoration: none;
  transition: border-color var(--transition), color var(--transition);
}

.btn-ghost:hover {
  border-color: var(--gold-400);
  color: var(--gold-600);
}

/* ── Right column ───────────────────────────────────── */
.right-col {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-end;
  padding: 3rem 0 3rem 1.5rem;
  border-left: 1px solid var(--border);
}

.attributes {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: flex-end;
}

.attr {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.15rem;
}

.attr-label {
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
  opacity: 0.7;
}

.attr-value {
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-style: italic;
  color: var(--text-secondary);
}

.scroll-ornament {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  color: var(--gold-400);
  opacity: 0.6;
}

.ornament-line {
  display: block;
  width: 1px;
  height: 40px;
  background: currentColor;
}

.ornament-glyph {
  font-size: 0.75rem;
}

.right-label {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  opacity: 0.6;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  transform: rotate(180deg);
}

/* ── Reduced motion ─────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .btn-primary, .btn-ghost, .nav-item { transition: none; }
}

/* ════════════════════════════════════════════════════════
   TIMELINES PAGE
   ════════════════════════════════════════════════════════ */

.tl-page {
  min-height: 100vh;
  background: var(--gold-100);
  background-image:
    radial-gradient(ellipse 80% 50% at 50% 0%, rgba(251, 191, 36, 0.14) 0%, transparent 60%);
  color: var(--text-primary);
  font-family: var(--font-body);
  overflow-y: auto;
  overflow-x: hidden;
}

/* ── Header ─────────────────────────────────────────── */
.tl-header {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
  padding: 2rem 3rem 1.5rem;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: rgba(255, 251, 240, 0.92);
  backdrop-filter: blur(10px);
  z-index: 20;
}

.tl-back {
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-decoration: none;
  transition: color var(--transition);
  justify-self: start;
}

.tl-back:hover { color: var(--gold-500); }

.tl-title-group { text-align: center; }

.tl-eyebrow {
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.2rem;
}

.tl-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 400;
  color: var(--amber-deep);
  letter-spacing: -0.01em;
  line-height: 1;
}

.tl-subtitle {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 0.2rem;
}

.tl-compare-toggle {
  justify-self: end;
  padding: 0.45rem 1rem;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 0.75rem;
  font-family: var(--font-body);
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  cursor: pointer;
  transition: border-color var(--transition), color var(--transition);
}

.tl-compare-toggle:hover {
  border-color: var(--gold-400);
  color: var(--gold-600);
}

/* ── Comparison table ───────────────────────────────── */
.tl-comparison {
  padding: 1.5rem 3rem;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
}

.compare-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

.compare-table th,
.compare-table td {
  padding: 0.6rem 1rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
  line-height: 1.5;
}

.compare-table thead th {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  font-weight: 600;
  padding-bottom: 0.75rem;
}

.col-aspect { width: 18%; }
.col-a      { width: 41%; }
.col-b      { width: 41%; }

.cell-aspect {
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  font-weight: 600;
  white-space: nowrap;
}

.cell-a { color: var(--text-secondary); }
.cell-b { color: var(--text-secondary); }

.col-a, .cell-a { border-right: 1px solid var(--border); }

/* ── Timeline grid ──────────────────────────────────── */
.tl-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  padding: 2.5rem 3rem 4rem;
  max-width: 1280px;
  margin: 0 auto;
}

.tl-column { padding: 0 1.5rem; }
.tl-column + .tl-column { border-left: 1px solid var(--border); }

/* ── Column header ──────────────────────────────────── */
.tl-col-header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 2rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border);
}

.tl-eye-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  margin-top: 0.35rem;
  flex-shrink: 0;
  box-shadow: 0 0 10px currentColor;
}

.tl-col-label {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 400;
  color: var(--amber-deep);
  line-height: 1;
  margin-bottom: 0.2rem;
}

.tl-col-eyebrow {
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.tl-col-descriptor {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ── Beat cards ─────────────────────────────────────── */
.beats-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.beat-card {
  border: 1px solid var(--border);
  border-radius: 6px;
  background: rgba(255, 251, 240, 0.5);
  overflow: hidden;
  transition: border-color var(--transition), background var(--transition);
}

.beat-card.is-open {
  background: rgba(255, 251, 240, 0.95);
  border-color: rgba(245, 158, 11, 0.45);
}

.beat-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-body);
}

.beat-index {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  flex-shrink: 0;
  width: 1.5rem;
}

.beat-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--amber-deep);
  flex: 1;
  text-transform: capitalize;
}

.beat-chevron {
  font-size: 1rem;
  color: var(--gold-500);
  flex-shrink: 0;
  line-height: 1;
}

.beat-summary {
  padding: 0 1rem 0.75rem calc(0.75rem + 1.5rem + 1rem);
  font-size: 0.82rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.beat-detail {
  padding: 0.75rem 1rem 1rem calc(0.75rem + 1.5rem + 1rem);
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.875rem;
  line-height: 1.75;
  color: var(--text-primary);
  border-top: 1px solid var(--border);
}

/* ── Footer ─────────────────────────────────────────── */
.tl-footer {
  text-align: center;
  padding: 1.5rem;
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  opacity: 0.6;
  border-top: 1px solid var(--border);
}

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 768px) {
  .tl-header {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto;
    text-align: center;
    padding: 1.5rem;
    gap: 0.75rem;
  }

  .tl-back, .tl-compare-toggle { justify-self: center; }

  .tl-grid {
    grid-template-columns: 1fr;
    padding: 1.5rem;
  }

  .tl-column + .tl-column {
    border-left: none;
    border-top: 1px solid var(--border);
    margin-top: 2rem;
    padding-top: 2rem;
  }

  .tl-comparison { padding: 1rem 1.5rem; }
}

@media (prefers-reduced-motion: reduce) {
  .beat-card { transition: none; }
}

/* ════════════════════════════════════════════════════════
   CONNECTIONS PAGE
   ════════════════════════════════════════════════════════ */

.cn-page {
  min-height: 100vh;
  background: var(--gold-100);
  background-image:
    radial-gradient(ellipse 80% 50% at 50% 0%, rgba(251, 191, 36, 0.14) 0%, transparent 60%);
  font-family: var(--font-body);
  color: var(--text-primary);
  display: flex;
  flex-direction: column;
}

.cn-header-right { justify-self: end; }

/* ── Filters ────────────────────────────────────────── */
.cn-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 1.25rem 3rem;
  border-bottom: 1px solid var(--border);
}

.cn-filter-btn {
  padding: 0.3rem 0.9rem;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.72rem;
  font-family: var(--font-body);
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.cn-filter-btn:hover {
  border-color: var(--gold-400);
  color: var(--gold-600);
}

.cn-filter-btn.is-active {
  background: var(--gold-500);
  border-color: var(--gold-500);
  color: #fff;
}

/* ── Body layout ────────────────────────────────────── */
.cn-body {
  display: grid;
  grid-template-columns: 1fr 340px;
  flex: 1;
  min-height: 0;
}

/* ── Card grid ──────────────────────────────────────── */
.cn-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
  padding: 2rem 3rem;
  align-content: start;
  overflow-y: auto;
}

/* Bond color coding via dot */
.cn-bond-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.bond-divine   .cn-bond-dot { background: #a78bfa; }
.bond-family   .cn-bond-dot { background: #f97316; }
.bond-ally     .cn-bond-dot { background: var(--gold-400); }
.bond-ward     .cn-bond-dot { background: #34d399; }
.bond-child    .cn-bond-dot { background: #fb923c; }
.bond-adversary .cn-bond-dot { background: #f87171; }

.cn-card {
  background: rgba(255, 251, 240, 0.6);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  text-align: left;
  cursor: pointer;
  font-family: var(--font-body);
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.cn-card:hover {
  border-color: rgba(245, 158, 11, 0.4);
  background: rgba(255, 251, 240, 0.9);
  transform: translateY(-2px);
}

.cn-card.is-selected {
  border-color: var(--gold-500);
  background: rgba(255, 251, 240, 0.95);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
}

.cn-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.2rem;
}

.cn-presence-tag {
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  opacity: 0.7;
}

.presence-a  .cn-presence-tag { color: #60a5fa; opacity: 1; }
.presence-b  .cn-presence-tag { color: #34d399; opacity: 1; }
.presence-both .cn-presence-tag { color: var(--text-muted); }

.cn-card-name {
  font-family: var(--font-display);
  font-size: 1.05rem;
  color: var(--amber-deep);
  font-weight: 400;
}

.cn-card-title {
  font-size: 0.72rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

.cn-card-bond {
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: 0.2rem;
}

/* ── Detail panel ───────────────────────────────────── */
.cn-detail {
  border-left: 1px solid var(--border);
  overflow-y: auto;
  position: sticky;
  top: 0;
  max-height: calc(100vh - 120px);
  background: rgba(255, 251, 240, 0.97);
}

.cn-detail-inner {
  padding: 2rem 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.cn-detail-close {
  align-self: flex-end;
  background: transparent;
  border: none;
  font-size: 0.9rem;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  transition: color var(--transition);
}

.cn-detail-close:hover { color: var(--gold-600); }

.cn-detail-eyebrow {
  font-size: 0.65rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.cn-detail-name {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 400;
  color: var(--amber-deep);
  line-height: 1;
}

.cn-detail-title {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-top: -0.5rem;
}

.cn-detail-entries {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 0.25rem;
}

.cn-detail-entry {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.cn-entry-label {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.15rem 0.5rem;
  border-radius: 3px;
  align-self: flex-start;
}

.cn-label-a {
  background: rgba(96, 165, 250, 0.15);
  color: #1d4ed8;
}

.cn-label-b {
  background: rgba(52, 211, 153, 0.15);
  color: #065f46;
}

.cn-entry-text {
  font-size: 0.85rem;
  line-height: 1.7;
  color: var(--text-primary);
}

.cn-detail-quote {
  margin-top: 0.5rem;
  padding: 0.75rem 1rem;
  border-left: 2px solid var(--gold-300);
  background: rgba(252, 211, 77, 0.08);
  border-radius: 0 4px 4px 0;
}

.cn-detail-quote p {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.875rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

.cn-detail-quote cite {
  display: block;
  margin-top: 0.5rem;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  font-style: normal;
}

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 900px) {
  .cn-body {
    grid-template-columns: 1fr;
  }

  .cn-detail {
    position: static;
    max-height: none;
    border-left: none;
    border-top: 1px solid var(--border);
  }

  .cn-grid {
    padding: 1.5rem;
  }

  .cn-filters {
    padding: 1rem 1.5rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cn-card, .cn-filter-btn { transition: none; }
}

