  margin-bottom: 0.6rem;
  text-transform: capitalize;
}

.wb-section-intro {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--text-secondary);
  line-height: 1.65;
  max-width: 56ch;
}

/* ── Entries ────────────────────────────────────────── */
.wb-entries {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.wb-entry {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 0 2rem;
  padding: 1.1rem 0;
  border-bottom: 1px solid var(--border);
}

.wb-entry:last-child { border-bottom: none; }

.wb-term {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gold-600);
  padding-top: 0.15rem;
  line-height: 1.5;
}

.wb-body {
  font-size: 0.9rem;
  line-height: 1.75;
  color: var(--text-primary);
  font-style: normal;
}

.wb-note {
  grid-column: 2;
  margin-top: 0.5rem;
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.82rem;
  color: var(--text-secondary);
  padding-left: 0.75rem;
  border-left: 2px solid var(--gold-300);
}

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 768px) {
  .wb-main { padding: 1.5rem; }

  .wb-layout {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .wb-nav {
    position: static;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 0.4rem;
  }

  .wb-nav-item {
    border-left: none;
    border-bottom: 2px solid transparent;
    padding: 0.3rem 0.6rem;
  }

  .wb-nav-item.is-active {
    border-left-color: transparent;
    border-bottom-color: var(--gold-500);
  }

  .wb-entry {
    grid-template-columns: 1fr;
    gap: 0.35rem;
  }

  .wb-note { grid-column: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .wb-section { animation: none; }
  .wb-nav-item { transition: none; }
}

