  font-style: italic;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ── Beat cards ─────────────────────────────────────── */
.beats-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.beat-card {
  border: 1px solid var(--border);
  border-radius: 6px;
  background: rgba(255, 251, 240, 0.5);
  overflow: hidden;
  transition: border-color var(--transition), background var(--transition);
}

.beat-card.is-open {
  background: rgba(255, 251, 240, 0.95);
  border-color: rgba(245, 158, 11, 0.45);
}

.beat-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-body);
}

.beat-index {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  flex-shrink: 0;
  width: 1.5rem;
}

.beat-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--amber-deep);
  flex: 1;
  text-transform: capitalize;
}

.beat-chevron {
  font-size: 1rem;
  color: var(--gold-500);
  flex-shrink: 0;
  line-height: 1;
}

.beat-summary {
  padding: 0 1rem 0.75rem calc(0.75rem + 1.5rem + 1rem);
  font-size: 0.82rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.beat-detail {
  padding: 0.75rem 1rem 1rem calc(0.75rem + 1.5rem + 1rem);
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.875rem;
